"""Reference-grounded table: primary controls fit phones and outcomes remain authoritative."""
import os,json
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
base=os.environ.get('UNITY_URL','http://127.0.0.1:3483');out=Path(os.environ.get('BACCARAT_TABLE_QA','/workspace/scratch/baccarat-table'));out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844},has_touch=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base+'/baccarat/index.html');page.locator('[data-action=tables]').click();page.locator('[data-action="start:lounge"]').click();boxes=[]
 for w,h in [(375,812),(390,844),(414,896),(1920,1080)]:
  page.set_viewport_size({'width':w,'height':h});page.evaluate('()=>scrollTo(0,0)');page.wait_for_timeout(150);box=page.locator('[data-action=confirm]').bounding_box();assert box['y']+box['height']<=h-4,(w,h,box);assert not page.evaluate('()=>document.documentElement.scrollWidth>innerWidth');assert page.locator('.chip').first.bounding_box()['height']>=44;page.screenshot(path=str(out/f'betting-{w}.png'),full_page=True);boxes.append({'width':w,'height':h,'confirm':box})
 page.set_viewport_size({'width':390,'height':844});page.locator('[data-action="bet:player"]').click();expect(page.locator('[data-action=confirm]')).to_be_enabled();page.locator('[data-action=confirm]').dblclick();expect(page.locator('#squeeze-dialog')).to_be_visible(timeout=15000);page.locator('[data-show=skip]').click();expect(page.locator('[data-action=next]')).to_be_visible();assert page.evaluate('()=>BACCARAT.session.state.stats.rounds')==1;balance=page.evaluate('()=>BACCARAT.session.state.balance');page.locator('[data-action=\"inspect-hand:player\"]').click();expect(page.locator('.hand-zoom img').first).to_be_visible();assert page.locator('.hand-zoom img').count()==page.evaluate('()=>BACCARAT.session.state.round.plan.cards.filter(x=>x.side===\"player\").length');assert page.locator('.hand-zoom img').first.bounding_box()['width']>=115;page.keyboard.press('Escape');page.reload();page.locator('[data-action=continue]').click();assert page.evaluate('()=>BACCARAT.session.state.balance')==balance;assert page.evaluate('()=>BACCARAT.session.state.stats.rounds')==1;page.locator('[data-action=next]').click();page.locator('[data-action=repeat]').click();expect(page.locator('[data-action=confirm]')).to_be_enabled();assert not errors,errors
 (out/'table-report.json').write_text(json.dumps({'viewports':boxes,'singleSettlement':True,'reloadBalance':balance,'errors':errors},indent=2));b.close()
print('compact table viewports and real round integrity passed')
